PRAGMA foreign_keys = ON;
CREATE TABLE leads (id INTEGER PRIMARY KEY AUTOINCREMENT, company TEXT NOT NULL, division TEXT NOT NULL CHECK(division IN ('Engineering','Software')), service TEXT, website TEXT, contact_name TEXT, contact_email TEXT, source_name TEXT, source_url TEXT, buyer_evidence TEXT, qualification_reason TEXT, ai_score INTEGER DEFAULT 0, priority TEXT DEFAULT 'Medium', email_verified INTEGER DEFAULT 0, qualification_status TEXT DEFAULT 'New', pipeline_stage TEXT DEFAULT 'New Lead', outreach_status TEXT DEFAULT 'Not Ready', outreach_attempts INTEGER DEFAULT 0, last_outreach_at TEXT, next_followup_at TEXT, reply_status TEXT, meeting_status TEXT, quote_status TEXT, client_status TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX idx_leads_email ON leads(contact_email) WHERE contact_email IS NOT NULL AND contact_email <> '';
CREATE INDEX idx_leads_division_status ON leads(division, qualification_status);
CREATE TABLE discovery_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, run_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, engineering_found INTEGER DEFAULT 0, software_found INTEGER DEFAULT 0, qualified INTEGER DEFAULT 0, rejected INTEGER DEFAULT 0, dry_run INTEGER DEFAULT 1, summary TEXT, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at TEXT);
CREATE TABLE discovery_candidates (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER, company TEXT NOT NULL, division TEXT NOT NULL, service TEXT, website TEXT, contact_name TEXT, contact_email TEXT, source_name TEXT, source_url TEXT, evidence TEXT, ai_score INTEGER DEFAULT 0, decision TEXT NOT NULL, decision_reason TEXT, lead_id INTEGER, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(run_id) REFERENCES discovery_runs(id), FOREIGN KEY(lead_id) REFERENCES leads(id));
CREATE TABLE outreach_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, division TEXT NOT NULL, recipient TEXT NOT NULL, sender TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, gmail_message_id TEXT UNIQUE, gmail_thread_id TEXT, status TEXT NOT NULL DEFAULT 'Queued', attempt_number INTEGER DEFAULT 1, sent_at TEXT, error_message TEXT, archive_status TEXT, label_status TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(lead_id) REFERENCES leads(id));
CREATE INDEX idx_outreach_sent ON outreach_messages(sent_at, division);
CREATE TABLE followups (id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, outreach_message_id INTEGER, sequence_number INTEGER NOT NULL, due_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Scheduled', sent_at TEXT, cancelled_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(lead_id) REFERENCES leads(id), FOREIGN KEY(outreach_message_id) REFERENCES outreach_messages(id));
CREATE TABLE replies (id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER NOT NULL, gmail_message_id TEXT NOT NULL UNIQUE, gmail_thread_id TEXT, from_email TEXT, classification TEXT NOT NULL, summary TEXT, received_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(lead_id) REFERENCES leads(id));
CREATE TABLE suppressions (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, reason TEXT NOT NULL, source TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE activities (id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id INTEGER, type TEXT NOT NULL, description TEXT NOT NULL, metadata_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(lead_id) REFERENCES leads(id));
CREATE INDEX idx_activities_lead ON activities(lead_id, created_at);
CREATE TABLE daily_reports (report_date TEXT PRIMARY KEY, leads_found INTEGER DEFAULT 0, qualified INTEGER DEFAULT 0, engineering_sent INTEGER DEFAULT 0, software_sent INTEGER DEFAULT 0, total_sent INTEGER DEFAULT 0, followups_sent INTEGER DEFAULT 0, replies INTEGER DEFAULT 0, interested INTEGER DEFAULT 0, bounced INTEGER DEFAULT 0, failed INTEGER DEFAULT 0, skipped INTEGER DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
